"const fs = require('fs');
const readline = require('readline');

const logFile = 'C:\\Users\\Balamurugan\\.gemini\\antigravity-ide\\brain\\14342646-882e-4d6c-83a2-5752e47c2cbe\\.system_generated\\logs\\transcript.jsonl';

async function run() {
  const fileStream = fs.createReadStream(logFile);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    if (!line) continue;
    try {
      const step = JSON.parse(line);
      if (step.step_index === 403) {
        console.log('--- FOUND STEP 403 ---');
        fs.writeFileSync('scratch/recovered_step_403.txt', step.content || '');
        console.log('Saved to scratch/recovered_step_403.txt');
      }
    } catch (e) {
      // ignore
    }
  }
}

run();
"
